<?php require_once 'config.php';require_login();$page_title='Mutasi Warga';$page_desc='Pencatatan pindah masuk, pindah keluar, kelahiran, dan kematian.';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('INSERT INTO mutasi(warga_id,tanggal,jenis,keterangan) VALUES(?,?,?,?)');$s->execute([(int)$_POST['warga_id'],date('Y-m-d'),$_POST['jenis'],trim($_POST['keterangan'])]);flash('success','Data mutasi berhasil dicatat.');header('Location: mutasi.php');exit;}$warga=$pdo->query('SELECT id,nama FROM warga ORDER BY nama')->fetchAll();$rows=$pdo->query('SELECT m.*,w.nama FROM mutasi m JOIN warga w ON w.id=m.warga_id ORDER BY m.id DESC')->fetchAll();require 'partials/header.php';?><section class="panel form-panel"><div class="panel-head"><h3>Catat Mutasi Baru</h3></div><form method="post" class="form-grid"><div><label>Nama Warga</label><select name="warga_id" required><?php foreach($warga as $w): ?><option value="<?=$w['id']?>"><?=e($w['nama'])?></option><?php endforeach;?></select></div><div><label>Jenis Mutasi</label><select name="jenis"><option>Pindah Masuk</option><option>Pindah Keluar</option><option>Kelahiran</option><option>Kematian</option></select></div><div class="full-col"><label>Keterangan</label><textarea name="keterangan" rows="3"></textarea></div><div><button class="btn primary">Simpan Mutasi</button></div></form></section><section class="panel"><div class="panel-head"><h3>Riwayat Mutasi</h3></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Nama</th><th>Jenis</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $m): ?><tr><td><?=date('d-m-Y',strtotime($m['tanggal']))?></td><td><?=e($m['nama'])?></td><td><span class="badge"><?=e($m['jenis'])?></span></td><td><?=e($m['keterangan'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require 'partials/footer.php';?>
